"""Self-contained review view; all dynamic data are escaped before rendering."""
from __future__ import annotations

import html
import json
import re


def render_dashboard(summary: dict) -> str:
    data = json.dumps(summary, ensure_ascii=True, allow_nan=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    title = html.escape(summary.get("market_name", "Synthetic settlement replay"))
    replacements = {"__TITLE__": title, "__DATA__": data}
    return re.sub(r"__TITLE__|__DATA__", lambda match: replacements[match.group()], TEMPLATE)


